
-- Handbook v1.14 remediation: distinct study/family notifications replace generic feed entries.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'translated record' WHEN 1 THEN 'stepstranslated record' WHEN 2 THEN 'follow-up appointmenttranslated record'
      WHEN 3 THEN 'translated recordbudgettranslated record' WHEN 4 THEN 'translated record' WHEN 5 THEN 'translated record'
      WHEN 6 THEN 'translated record' WHEN 7 THEN 'rehabilitationtranslated record' WHEN 8 THEN 'translated recordemailtranslated record'
      WHEN 9 THEN 'translated recordexamtranslated record' WHEN 10 THEN 'translated record' WHEN 11 THEN 'translated record'
      WHEN 12 THEN 'translated record' WHEN 13 THEN 'translated record' WHEN 14 THEN 'translated recordordertranslated record'
      WHEN 15 THEN 'translated record' ELSE 'translated record' END AS notice_fact,
    CASE rowid % 19
      WHEN 0 THEN 'record only; no action needed' WHEN 1 THEN 'translated record' WHEN 2 THEN 'translated record' WHEN 3 THEN 'will not auto-order'
      WHEN 4 THEN 'will not auto-pay' WHEN 5 THEN 'handle in the next study block' WHEN 6 THEN 'translated recordpaintranslated record' WHEN 7 THEN 'check calendar conflicts first'
      WHEN 8 THEN 'check remaining budget first' WHEN 9 THEN 'translated record' WHEN 10 THEN 'translated recordZhang Mingtranslated record' WHEN 11 THEN 'translated record'
      WHEN 12 THEN 'historical records remain searchable' WHEN 13 THEN 'mark read after handling' WHEN 14 THEN 'translated recordexamtranslated record' WHEN 15 THEN 'translated record'
      WHEN 16 THEN 'translated record' WHEN 17 THEN 'translated record' ELSE 'translated record' END AS notice_scope
  FROM notifications WHERE notification_id LIKE 'notif_bg_%'
)
UPDATE notifications
SET source=CASE rowid % 4 WHEN 0 THEN 'study_planner' WHEN 1 THEN 'family_care' WHEN 2 THEN 'budget_monitor' ELSE 'household_service' END,
    title=(SELECT notice_fact FROM facts WHERE facts.rid=notifications.rowid),
    body=CASE rowid % 5
      WHEN 0 THEN (SELECT notice_fact || '；' || notice_scope || '。' FROM facts WHERE facts.rid=notifications.rowid)
      WHEN 1 THEN (SELECT 'translated record：' || notice_fact || '。translated record：' || notice_scope || '。' FROM facts WHERE facts.rid=notifications.rowid)
      WHEN 2 THEN (SELECT notice_scope || '；translated record' || notice_fact || '。' FROM facts WHERE facts.rid=notifications.rowid)
      WHEN 3 THEN (SELECT 'translated record' || notice_fact || '，translated record' || notice_scope || '。' FROM facts WHERE facts.rid=notifications.rowid)
      ELSE (SELECT notice_fact || 'translated record。' || notice_scope || '。' FROM facts WHERE facts.rid=notifications.rowid)
    END,
    payload_json=json_object('record_kind','context_notice','actionable',0,'source_class',CASE rowid % 4 WHEN 0 THEN 'study' WHEN 1 THEN 'care' WHEN 2 THEN 'budget' ELSE 'household' END),
    notification_id=replace(notification_id,'notif_bg_','notif_context_')
WHERE notification_id LIKE 'notif_bg_%';
